pub assume_specification<T, E>[ Result::<T, E>::as_mut ](
    result: &mut Result<T, E>,
) -> (res: Result<&mut T, &mut E>)
    ensures
        (match *old(result) {
            Result::Ok(v) => {
                &&& res is Ok
                &&& *res->Ok_0 == v
                &&& *final(result) == Result::<T, E>::Ok(*final(res->Ok_0))
            },
            Result::Err(e) => {
                &&& res is Err
                &&& *res->Err_0 == e
                &&& *final(result) == Result::<T, E>::Err(*final(res->Err_0))
            },
        }),
;
